import React, { useState, useEffect, useImperativeHandle, forwardRef } from "react";
import { cn } from "../lib/utils";

export interface CryptextRef {
  /** Reinicia la animación de decodificación desde cero programáticamente. */
  scramble: () => void;
}

/** 
 * Propiedades de configuración para el componente de animación de texto.
 */
export interface CryptextProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** 
   * El texto final a revelar. 
   * @example "VOYNICH_PROTOCOL"
   */
  text: string;
  /** 
   * Caracteres que se rotarán al azar durante la fase de encriptación.
   * @default "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+{}|:<>?-=[];,./"
   */
  dictionary?: string;
  /** 
   * Velocidad en milisegundos a la que mutan los caracteres o se actualiza cada frame.
   * @default 50 
   */
  speed?: number;
  /** 
   * Retraso total (en ms) antes de que el componente empiece a fijar progresivamente las letras correctas.
   * @default 800
   */
  delay?: number;
  /** 
   * Cantidad de caracteres reales que se "resuelven" por cada ciclo/frame después del delay inicial.
   * @default 1
   */
  resolvePerFrame?: number;
  /** 
   * El elemento o etiqueta HTML subyacente para renderizar.
   * @default "span"
   */
  as?: React.ElementType;
}

const DEFAULT_DICT = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+{}|:<>?-=[];,./";

/**
 * `Cryptext`
 * 
 * Un componente envoltura polimórfico de texto que muestra una animación de "desencriptado"
 * matricial. Transiciona desde caracteres aleatorios hasta revelar la información.
 * Puede ser reiniciado mediante referencias (ref) para interactividad UI.
 */
export const Cryptext = forwardRef<CryptextRef, CryptextProps>(
  (
    {
      text,
      dictionary = DEFAULT_DICT,
      speed = 50,
      delay = 800,
      resolvePerFrame = 1,
      as: Tag = "span",
      className,
      ...props
    },
    ref
  ) => {
    const [currentText, setCurrentText] = useState(text);
    const [isAnimating, setIsAnimating] = useState(false);

    const scrambleText = () => {
      setIsAnimating(true);
      let iteration = 0;
      // iterations is artificially padded by delay/speed to stay entirely scrambled for a while
      const maxIterations = Math.max(text.length / resolvePerFrame, delay / speed);

      const interval = setInterval(() => {
        setCurrentText((prev) => {
          let newStr = "";
          // El calculo ajusta la iteración restando los "frames muertos" generados por el delay.
          const effectiveIteration = iteration - (delay / speed);

          for (let i = 0; i < text.length; i++) {
            if (i < effectiveIteration * resolvePerFrame || text[i] === " ") {
              newStr += text[i];
            } else {
              newStr += dictionary[Math.floor(Math.random() * dictionary.length)];
            }
          }
          return newStr;
        });

        if (iteration >= (text.length / resolvePerFrame) + (delay / speed)) {
          clearInterval(interval);
          setIsAnimating(false);
          setCurrentText(text); 
        }
        iteration++;
      }, speed);
    };

    useImperativeHandle(ref, () => ({
      scramble: scrambleText,
    }));

    useEffect(() => {
      scrambleText();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [text]);

    return (
      <Tag className={cn("font-mono", className)} {...props}>
        {currentText}
      </Tag>
    );
  }
);
Cryptext.displayName = "Cryptext";
