import React, {
  useRef,
  useState,
  forwardRef,
  useImperativeHandle,
} from "react";
import { cn } from "../lib/utils";

export type LensShape = "circle" | "square" | "rounded-square";
export type LensFilter = "none" | "sepia" | "grayscale" | "invert" | "vintage" | "x-ray";

export interface LensMagnifierProps extends React.HTMLAttributes<HTMLDivElement> {
  src: string;
  alt?: string;
  zoomLevel?: number;
  lensSize?: number;
  lensBorder?: number;
  lensShape?: LensShape;
  lensColor?: string;
  filter?: LensFilter;
  showHandle?: boolean;
  smoothFollowing?: boolean;
}

export interface LensMagnifierRef {
  resetZoom: () => void;
}

export const LensMagnifier = forwardRef<LensMagnifierRef, LensMagnifierProps>(
  (
    {
      src,
      alt = "Magnifiable Content",
      zoomLevel = 2,
      lensSize = 150,
      lensBorder = 4,
      lensShape = "circle",
      lensColor = "border-slate-300/50",
      filter = "none",
      showHandle = false,
      smoothFollowing = true,
      className,
      ...props
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const lensRef = useRef<HTMLDivElement>(null);
    const zoomedImgRef = useRef<HTMLImageElement>(null);

    const [isActive, setIsActive] = useState(false);

    const pos = useRef({ x: 0, y: 0 });
    const targetPos = useRef({ x: 0, y: 0 });
    const containerSize = useRef({ w: 0, h: 0 });

    useImperativeHandle(ref, () => ({
      resetZoom: () => setIsActive(false),
    }));

    React.useEffect(() => {
      if (!isActive) return;

      let animationFrameId: number;

      const updateDOM = (x: number, y: number) => {
        if (lensRef.current) {
          lensRef.current.style.transform = `translate(${x - lensSize / 2}px, ${y - lensSize / 2}px)`;
        }

        if (zoomedImgRef.current && containerSize.current.w > 0) {
          const cW = containerSize.current.w;
          const cH = containerSize.current.h;

          zoomedImgRef.current.style.width = `${cW * zoomLevel}px`;
          zoomedImgRef.current.style.height = `${cH * zoomLevel}px`;

          const bgX = x * -zoomLevel + lensSize / 2;
          const bgY = y * -zoomLevel + lensSize / 2;
          zoomedImgRef.current.style.transform = `translate(${bgX}px, ${bgY}px)`;
        }
      };

      const renderLoop = () => {
        if (smoothFollowing) {
          pos.current.x += (targetPos.current.x - pos.current.x) * 0.15;
          pos.current.y += (targetPos.current.y - pos.current.y) * 0.15;
        } else {
          pos.current.x = targetPos.current.x;
          pos.current.y = targetPos.current.y;
        }

        updateDOM(pos.current.x, pos.current.y);
        animationFrameId = requestAnimationFrame(renderLoop);
      };

      if (!smoothFollowing) {
        pos.current.x = targetPos.current.x;
        pos.current.y = targetPos.current.y;
        updateDOM(pos.current.x, pos.current.y);
      }

      animationFrameId = requestAnimationFrame(renderLoop);

      return () => cancelAnimationFrame(animationFrameId);
    }, [isActive, smoothFollowing, zoomLevel, lensSize]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      targetPos.current.x = e.clientX - rect.left;
      targetPos.current.y = e.clientY - rect.top;

      if (!isActive) {
        containerSize.current.w = containerRef.current.offsetWidth;
        containerSize.current.h = containerRef.current.offsetHeight;
        setIsActive(true);
      }
    };

    const handleMouseEnter = () => {
      if (containerRef.current) {
        containerSize.current.w = containerRef.current.offsetWidth;
        containerSize.current.h = containerRef.current.offsetHeight;
      }
      setIsActive(true);
    };

    const handleMouseLeave = () => {
      setIsActive(false);
    };

    const getShapeRadius = (shape: LensShape) => {
      switch (shape) {
        case "square": return "0%";
        case "rounded-square": return "15%";
        case "circle":
        default: return "50%";
      }
    };

    const getFilterStyle = (f: LensFilter) => {
      switch (f) {
        case "sepia": return "sepia(80%) contrast(1.2)";
        case "grayscale": return "grayscale(100%) contrast(1.2)";
        case "invert": return "invert(100%) hue-rotate(180deg)";
        case "vintage": return "sepia(50%) contrast(1.5) brightness(0.9) hue-rotate(-15deg)";
        case "x-ray": return "invert(100%) grayscale(100%) contrast(2)";
        case "none":
        default: return "none";
      }
    };

    return (
      <div
        ref={containerRef}
        className={cn(
          "relative overflow-hidden cursor-none select-none group border border-slate-200 bg-slate-50",
          className,
        )}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        onMouseEnter={handleMouseEnter}
        {...props}
      >
        <img
          src={src}
          alt={alt}
          className="w-full h-full object-cover pointer-events-none transition-[filter] duration-300"
          style={{
            filter: isActive ? "brightness(0.9) grayscale(20%)" : "none",
          }}
          draggable={false}
        />

        <div
          ref={lensRef}
          className={cn(
            "absolute top-0 left-0 z-10 shadow-2xl pointer-events-none overflow-visible will-change-transform",
            isActive
              ? "opacity-100 duration-300 ease-out transition-opacity"
              : "opacity-0 duration-200 transition-opacity",
          )}
          style={{
            width: lensSize,
            height: lensSize,
          }}
        >
          {showHandle && lensShape === "circle" && (
            <div 
              className="absolute left-1/2 top-[95%] w-[12%] h-[80%] bg-gradient-to-r from-amber-800 via-amber-600 to-amber-900 rounded-b-md rounded-t-sm origin-top -translate-x-1/2 rotate-[35deg] shadow-xl z-0"
              style={{
                boxShadow: "inset -2px 0 6px rgba(0,0,0,0.5), inset 2px 0 4px rgba(255,255,255,0.3)"
              }}
            >
              <div className="absolute top-[10%] w-full h-[5%] bg-amber-950/50" />
              <div className="absolute top-[80%] w-full h-[5%] bg-amber-950/50" />
            </div>
          )}
          
          <div 
            className={cn(
              "absolute inset-0 overflow-hidden bg-white z-10",
              lensColor,
            )}
            style={{
              borderRadius: getShapeRadius(lensShape),
              borderWidth: lensBorder,
              boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5), inset 0 0 10px rgba(0,0,0,0.3)"
            }}
          >
            <div className="absolute inset-0 origin-top-left pointer-events-none blur-[0.3px]">
              <img
                ref={zoomedImgRef}
                src={src}
                alt="Zoomed"
                className="absolute max-w-none pointer-events-none will-change-transform object-cover"
                draggable={false}
                style={{
                  filter: getFilterStyle(filter)
                }}
              />
            </div>

            <div 
              className="absolute inset-0 pointer-events-none bg-gradient-to-br from-white/30 via-transparent to-black/10 mix-blend-overlay"
              style={{ borderRadius: getShapeRadius(lensShape) }}
            />
            {lensShape === "circle" && (
              <div className="absolute left-[15%] top-[10%] w-[30%] h-[15%] rounded-[100%] bg-white/20 -rotate-12 pointer-events-none blur-sm" />
            )}
          </div>
        </div>
      </div>
    );
  },
);

LensMagnifier.displayName = "LensMagnifier";
